entradas.sparql:
PREFIX ont: <http://www.semanticweb.org/ronaldo/ontologies/2026/3/ontologia_medicamentos.owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?med WHERE {
  ?med rdf:type ont:Medicamento .
  ?med ont:temPrincipioAtivo ont:amoxicilina .
}

PREFIX ont: <http://www.semanticweb.org/ronaldo/ontologies/2026/3/ontologia_medicamentos.owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?nome WHERE {
  ont:varfarina ont:interageCom ?pa .
  BIND(REPLACE(STR(?pa), ".*#", "") AS ?nome)
}
